 add({name:'upload_'+g.name+'_file',description:'Upload one file as base64; original file validators and limits apply (HEX 10 MiB, other files 20 MiB). No remote URL fetching. Reuse requestId for retries where supported.',inputSchema:payload({...g.keys,...(g.name==='transport'?{purpose:enumeration(['waybill','receipt','condition','expense']),revision:integer(1,1e9)}:{}),...(g.name==='service'?{purpose:enumeration(['before','intake','diagnosis','after','delivery','other'])}:{}),...(g.name==='firmware'?{}:{requestId:id}),filename:text('',180),base64:text('Standard base64 file bytes, without data URL prefix.',28*1024*1024)}),write:true,kind:g.kind,finance:g.finance,run:async(a,o)=>{if(!/^(?:[A-Za-z0-9+/]{4})*(?:[A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=)?$/.test(a.base64))throw new AccessError('Invalid base64.',400);const decoded=atob(a.base64);if(decoded.length>20*1024*1024)throw new AccessError('File too large.',413);const bytes=Uint8Array.from(decoded,c=>c.charCodeAt(0)),form=new FormData();form.append('file',new Blob([bytes],{type:'application/octet-stream'}),a.filename);const u=new URL(g.path,o);for(const k of [...queryKeys,'requestId',...(['service','transport'].includes(g.name)?['purpose']:[]),...(g.name==='transport'?['revision']:[])])if(a[k])u.searchParams.set(k,a[k]);return result(await g.route.POST(new Request(u,{method:'POST',headers:{origin:o},body:form})));}});
 add({name:'download_'+g.name+'_file',description:'Read an attachment in base64 chunks (at most 64 KiB). Use nextOffset until null. Original permissions and integrity checks apply.',inputSchema:obj({...g.keys,...(g.name==='firmware'?{}:{id}),offset:integer(0,25*1024*1024),length:integer(1,65536)},[...queryKeys,...(g.name==='firmware'?[]:['id'])]),write:false,kind:g.kind,finance:g.finance,run:async(a,o)=>{const r=await g.route.GET(req(o,g.path,'GET',undefined,Object.fromEntries([...queryKeys,'id'].map(k=>[k,a[k]]))));if(!r.ok)return result(r);const bytes=new Uint8Array(await r.arrayBuffer()),offset=a.offset||0,end=Math.min(bytes.length,offset+(a.length||65536));if(offset>bytes.length)throw new AccessError('Offset exceeds file length.',400);return {base64:btoa(String.fromCharCode(...bytes.slice(offset,end))),offset,nextOffset:end<bytes.length?end:null,totalBytes:bytes.length,contentDisposition:r.headers.get('content-disposition')};}});
