api('sales_monitor_apply','One confirmed monitoring operation. Manager: configure/goal/retire_goal/scan/assign/review_goal/report_read; finance only: recover_check; manager or assigned staff: followup/acknowledge. data carries fields specified below. Uses exact current revision. Notes and nextAction required for followup. No manual close of debt/check alerts; check recovery needs real cleared same-agent payment and never posts cash twice. Read guide and current data first. Never invent target, evidence or achieved sales.',payload({id,mode:enumeration(['configure','goal','retire_goal','scan','assign','review_goal','report_read','followup','acknowledge','recover_check']),data:obj({revision:integer(0,1e9),settings:obj({enabled:{type:'boolean'},dailyTime:text('Tehran HH:MM',5),weeklyTime:text('Saturday Tehran HH:MM',5),quarterlyTime:text('First Persian quarter day Tehran HH:MM',5),overdueDays:integer(1,365),overdueAmount:text('Integer IRR; zero disables amount test.',18),goalElapsed:integer(1,99),goalAchievement:integer(1,100),goalFinalElapsed:integer(2,100),goalFinalAchievement:integer(1,100),deliveryLateDays:integer(1,90),paymentHours:integer(1,168),returnCount:integer(2,100),returnDays:integer(7,365),responseHours:integer(1,168),escalationHours:integer(1,336)}),agentId:id,title:text('',200),start:text('Gregorian ISO day',10),end:text('',10),basis:enumeration(['net','units']),amount:text('Integer IRR or units for goal; IRR for recovery.',18),productIds:list(id,100),previousId:id,goalId:id,alertId:id,reportId:id,ownerId:id,due:text('Future ISO timestamp with timezone, maximum 30 days.',30),paymentId:id,creditId:id,nextAction:text('Concrete next step',2000),notes:text('Actual evidence, decision or follow-up',4000)},[])}),'/api/sales/monitor','POST',salesMonitorApi.POST,{},[],a=>({...a.data,id:a.id,mode:a.mode,confirmed:a.confirmed}));
